import 'server-only';

import type { DesignConversationTurn, DesignWorkbenchComponentGuide, DesignWorkbenchFoundationContext } from '@/app/design/workbench-types';

export type { DesignConversationTurn, DesignWorkbenchComponentGuide, DesignWorkbenchFoundationContext };

function asRecord(v: unknown): Record<string, unknown> | null {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null;
}

function pickString(obj: Record<string, unknown>, keys: string[]): string {
  for (const k of keys) {
    const v = obj[k];
    if (typeof v === 'string' && v.trim()) return v.trim();
    if (typeof v === 'number') return String(v);
  }
  return '';
}

/** Extract a compact foundation context from tokens.json / DB snapshot payload. */
export function serializeFoundationsFromTokens(payload: unknown): DesignWorkbenchFoundationContext {
  const doc = asRecord(payload);
  const local = doc ? asRecord(doc.localStyles) : null;
  const colors: DesignWorkbenchFoundationContext['colors'] = [];
  const typography: DesignWorkbenchFoundationContext['typography'] = [];
  const effects: DesignWorkbenchFoundationContext['effects'] = [];
  const spacing: DesignWorkbenchFoundationContext['spacing'] = [];

  const colorList = Array.isArray(local?.color) ? (local!.color as unknown[]) : [];
  for (const entry of colorList.slice(0, 120)) {
    const o = asRecord(entry);
    if (!o) continue;
    const name = pickString(o, ['name', 'title', 'id', 'key']);
    const value =
      pickString(o, ['value', 'hex', 'color', 'css']) ||
      (typeof o.values === 'object' && o.values !== null ? pickString(asRecord(o.values) ?? {}, ['hex', 'value', 'color']) : '');
    const group = pickString(o, ['group']);
    const subgroup = pickString(o, ['subgroup']);
    if (name || value) colors.push({ name: name || 'color', value: value || '—', group, subgroup });
  }

  const typoList = Array.isArray(local?.typography) ? (local!.typography as unknown[]) : [];
  for (const entry of typoList.slice(0, 32)) {
    const o = asRecord(entry);
    if (!o) continue;
    const name = pickString(o, ['name', 'title', 'id', 'key']);
    const vals = asRecord(o.values) ?? o;
    const font = pickString(vals, ['fontFamily', 'font', 'family']);
    const rawSize = pickString(vals, ['fontSize', 'size', 'fontSizePx']);
    const size = rawSize && !/px$/i.test(rawSize) ? `${rawSize}px` : rawSize;
    const weight = pickString(vals, ['fontWeight', 'weight', 'fontStyle']);
    const rawLh = pickString(vals, ['lineHeight', 'leading']);
    const lh = rawLh || '';
    const line = [font, size, weight, lh].filter(Boolean).join(' · ') || JSON.stringify(o).slice(0, 120);
    typography.push({ name: name || 'type', line });
  }

  const spacingList = Array.isArray(local?.spacing) ? (local!.spacing as unknown[]) : [];
  for (const entry of spacingList.slice(0, 32)) {
    const o = asRecord(entry);
    if (!o) continue;
    const name = pickString(o, ['name', 'title', 'id', 'key']);
    const value =
      pickString(o, ['value', 'px', 'rem', 'css']) ||
      (typeof o.values === 'object' && o.values !== null ? pickString(asRecord(o.values) ?? {}, ['value', 'px', 'rem']) : '');
    if (name || value) spacing.push({ name: name || 'space', value: value || '—' });
  }

  const effectList = Array.isArray(local?.effect) ? (local!.effect as unknown[]) : [];
  for (const entry of effectList.slice(0, 24)) {
    const o = asRecord(entry);
    if (!o) continue;
    const name = pickString(o, ['name', 'title', 'id', 'key']);
    const line = pickString(o, ['description', 'value', 'css']) || JSON.stringify(o).slice(0, 120);
    effects.push({ name: name || 'effect', line });
  }

  return { colors, typography, effects, spacing };
}

/**
 * Extract a compact foundation context from DTCG brand tokens + optional DTCG
 * spacing/typography strings. Used as a fallback for registries that only have
 * DTCG data (no Figma V1 snapshot) so the design workbench still gets branded
 * color and spacing context to send to the image generation model.
 */
export function serializeFoundationsFromDtcgData(opts: {
  /** DtcgBrandTokens: Record<brandName, Record<groupKey, {$type, $value}>> */
  brands: Record<string, Record<string, Record<string, unknown>>> | null;
  /** Parsed resolved DTCG JSON for spacing tokens */
  spacingDtcg?: unknown;
  /** Parsed resolved DTCG JSON for typography tokens */
  typographyDtcg?: unknown;
}): DesignWorkbenchFoundationContext {
  const colors: DesignWorkbenchFoundationContext['colors'] = [];
  const spacing: DesignWorkbenchFoundationContext['spacing'] = [];
  const typography: DesignWorkbenchFoundationContext['typography'] = [];

  // ── Colors from brand tokens ──────────────────────────────────────────────
  if (opts.brands) {
    for (const [brandName, brandGroups] of Object.entries(opts.brands)) {
      const group = brandName === 'default' ? '' : brandName;
      if (!brandGroups || typeof brandGroups !== 'object') continue;
      for (const [groupKey, token] of Object.entries(brandGroups)) {
        if (!token || typeof token !== 'object') continue;
        // Leaf token: has $type and $value
        if ('$type' in token && '$value' in token && token.$type === 'color') {
          const value = typeof token.$value === 'string' ? token.$value : '';
          if (value) colors.push({ name: groupKey, value, group, subgroup: '' });
        }
      }
    }
  }

  // ── Spacing from DTCG resolved JSON ──────────────────────────────────────
  const walkDtcgLeaves = (
    obj: Record<string, unknown>,
    prefix: string,
    out: { name: string; value: string }[]
  ) => {
    for (const [key, val] of Object.entries(obj)) {
      if (key.startsWith('$')) continue;
      const fullKey = prefix ? `${prefix}-${key}` : key;
      const node = val as Record<string, unknown>;
      if (node && typeof node === 'object') {
        if ('$value' in node) {
          const v = typeof node.$value === 'string' ? node.$value :
                    typeof node.$value === 'number' ? String(node.$value) : '';
          if (v) out.push({ name: fullKey, value: v });
        } else {
          walkDtcgLeaves(node as Record<string, unknown>, fullKey, out);
        }
      }
    }
  };

  if (opts.spacingDtcg && typeof opts.spacingDtcg === 'object') {
    // getDtcgTokenStrings wraps output under the type key ('spacing')
    const root = opts.spacingDtcg as Record<string, unknown>;
    const inner = root['spacing'] && typeof root['spacing'] === 'object'
      ? root['spacing'] as Record<string, unknown>
      : root;
    walkDtcgLeaves(inner, '', spacing);
  }

  // ── Typography from DTCG resolved JSON ───────────────────────────────────
  if (opts.typographyDtcg && typeof opts.typographyDtcg === 'object') {
    const root = opts.typographyDtcg as Record<string, unknown>;
    const inner = root['typography'] && typeof root['typography'] === 'object'
      ? root['typography'] as Record<string, unknown>
      : root;
    const leaves: { name: string; value: string }[] = [];
    walkDtcgLeaves(inner, '', leaves);
    for (const l of leaves.slice(0, 24)) {
      typography.push({ name: l.name, line: l.value });
    }
  }

  return { colors: colors.slice(0, 120), typography, effects: [], spacing: spacing.slice(0, 32) };
}

function formatFoundationsBlock(ctx: DesignWorkbenchFoundationContext, customFoundationImageIncluded = false): string {
  if (customFoundationImageIncluded) {
    return [
      '## Design system foundations (use strictly)',
      'A custom foundation reference image is attached to this request. Use that image only as a style reference and source of truth for colors, typography, spacing, effects, and component styling foundations.',
      'Do not reproduce the foundation reference image, token sheet, swatches, type samples, labels, or any foundation documentation as visible content in the generated design.',
    ].join('\n');
  }

  const lines: string[] = [
    '## Design system foundations (use strictly)',
    'Use these foundations only to style the generated design. Do not render foundation tokens, swatches, type samples, labels, or documentation as visible content.',
  ];
  if (ctx.colors.length) {
    lines.push('### Colors');
    for (const c of ctx.colors) lines.push(`- ${c.name}: ${c.value}`);
  } else {
    lines.push('### Colors', '- (none provided)');
  }
  if (ctx.typography.length) {
    lines.push('### Typography');
    for (const t of ctx.typography) lines.push(`- ${t.name}: ${t.line}`);
  }
  if (ctx.effects.length) {
    lines.push('### Effects / elevation');
    for (const e of ctx.effects) lines.push(`- ${e.name}: ${e.line}`);
  }
  if (ctx.spacing?.length) {
    lines.push('### Spacing scale');
    for (const s of ctx.spacing) lines.push(`- ${s.name}: ${s.value}`);
  }
  return lines.join('\n');
}

const SCREENSHOT_API_MARKER = '/api/handoff/ai/component-screenshot';

function formatComponentGuidesBlock(guides: DesignWorkbenchComponentGuide[]): string {
  if (!guides.length) return '## Component guides\n- (none selected)';
  const lines: string[] = ['## Component guides (layout / content patterns — do not copy pixels blindly; match semantics)'];
  for (const g of guides) {
    lines.push(`### ${g.title} (${g.id})${g.group ? ` — group: ${g.group}` : ''}`);
    if (g.previewKey) lines.push(`Selected preview variation key: ${g.previewKey}`);
    if (g.description) lines.push(g.description);
    if (g.propertiesSummary) lines.push(`Property schema (summary):\n${g.propertiesSummary}`);
    if (g.previewUrl?.includes(SCREENSHOT_API_MARKER)) {
      lines.push(
        'A raster screenshot of this component preview is included as one of the attached reference images for this request (PNG, same order as images sent to the image model).'
      );
    } else if (g.previewUrl) {
      lines.push(`Reference preview asset: ${g.previewUrl}`);
    }
  }
  return lines.join('\n');
}

function formatConversationBlock(history: DesignConversationTurn[]): string {
  if (!history.length) return '';
  const lines: string[] = ['## Prior iterations (continue from the latest visual intent)'];
  for (const turn of history) {
    const who = turn.role === 'user' ? 'User' : 'Assistant output';
    lines.push(`- **${who}**: ${turn.prompt}`);
  }
  return lines.join('\n');
}

function formatDesignGuidelinesBlock(markdown: string): string {
  const trimmed = markdown.trim();
  if (!trimmed) return '';
  return ['## Design.MD guidelines (use strictly)', trimmed].join('\n\n');
}

function formatBrandVoiceGuidelinesBlock(markdown: string): string {
  const trimmed = markdown.trim();
  if (!trimmed) return '';
  return [
    '## Brand voice & copy guidelines (use strictly)',
    'Apply these guidelines to all generated UI copy, including headlines, CTAs, labels, descriptions, sample content, and the amount of copy that should fit the design.',
    trimmed,
  ].join('\n\n');
}

function formatPromptImagesBlock(count: number): string {
  if (count <= 0) return '';
  const label = count === 1 ? 'image' : 'images';
  return [
    '## User-attached prompt images',
    `The user attached ${count} ${label} directly to this request. Treat these as request-specific visual references and prioritize them for the current user request, while still respecting the design system foundations and saved component references.`,
  ].join('\n');
}

function formatLayoutGuideBlock(description: string, imageIncluded: boolean): string {
  const trimmed = description.trim();
  if (!trimmed && !imageIncluded) return '';
  const lines = [
    '## Layout Guide (follow structure)',
    'The user attached a wireframe/layout reference for this request. Use it for layout structure only: hierarchy, alignment, grouping, spacing, columns, rows, cards, repeated items, image placeholders, text block sizes, and button placement.',
    'Do not copy colors, typography, brand marks, exact copy, imagery style, or visual design details from the Layout Guide. Apply the design system foundations and the user request on top of this structure.',
  ];
  if (imageIncluded) {
    lines.push('A Layout Guide reference image is included in the attached images. Prioritize it for page structure.');
  }
  if (trimmed) {
    lines.push(`Layout description: ${trimmed}`);
  }
  return lines.join('\n');
}

function formatAttachedImageOrderBlock(labels: string[]): string {
  if (!labels.length) return '';
  return ['## Attached image order', ...labels.map((label, index) => `${index + 1}. ${label}`)].join('\n');
}

const CANVAS_RULES = `## Output rules
- Canvas is 2048×1152 landscape. Compose the result like a polished desktop web page section, such as a hero, footer, feature band, or content block.
- Match the design system's colors, typography, spacing, and component semantics described above.
- Produce a polished marketing/product UI suitable for web.`;

/**
 * Full prompt sent to the image model (foundations + guides + history + user request).
 */
export function buildDesignGenerationPrompt({
  userPrompt,
  foundationContext,
  componentGuides,
  conversationHistory,
  designGuidelines = '',
  brandVoiceGuidelines = '',
  customFoundationImageIncluded = false,
  promptImageCount = 0,
  layoutGuideDescription = '',
  layoutGuideImageIncluded = false,
  attachedImageLabels = [],
}: {
  userPrompt: string;
  foundationContext: DesignWorkbenchFoundationContext;
  componentGuides: DesignWorkbenchComponentGuide[];
  conversationHistory: DesignConversationTurn[];
  designGuidelines?: string;
  brandVoiceGuidelines?: string;
  customFoundationImageIncluded?: boolean;
  promptImageCount?: number;
  layoutGuideDescription?: string;
  layoutGuideImageIncluded?: boolean;
  attachedImageLabels?: string[];
}): string {
  const parts = [
    'You are an expert product designer generating a UI mock as an image edit.',
    formatFoundationsBlock(foundationContext, customFoundationImageIncluded),
    formatComponentGuidesBlock(componentGuides),
    formatDesignGuidelinesBlock(designGuidelines),
    formatBrandVoiceGuidelinesBlock(brandVoiceGuidelines),
    formatConversationBlock(conversationHistory),
    formatPromptImagesBlock(promptImageCount),
    formatLayoutGuideBlock(layoutGuideDescription, layoutGuideImageIncluded),
    formatAttachedImageOrderBlock(attachedImageLabels),
    CANVAS_RULES,
    '## Current user request',
    userPrompt,
  ];
  return parts.filter(Boolean).join('\n\n');
}
